  .split(/\s+/)
  .map(w => w.replace(/[^a-z]/g, ''))
  .filter(w => w.length > 0);

// Count frequencies
const freq: Map<string, number> = new Map();
for (const word of words) {
  freq.set(word, (freq.get(word) || 0) + 1);
