3. **Finds primes**: Iterates from 2 to N, checking each number with trial division up to √n (skipping even numbers after 2).
4. **Outputs**: Collects all primes and prints them one per line using `console.log`. If there are no primes, nothing is printed.

code:
function isPrime(n: number): boolean {
  if (n < 2) return false;
  if (n === 2) return true;
  if (n % 2 === 0) return false;
  for (let i = 3; i <= Math.sqrt(n); i += 2) {
    if (n % i === 0) return false;
  }
  return true;
}

const N = parseInt(process.argv[2], 10);

if (isNaN(N) || N < 2) {
  // No primes to print
  process.exit(0);
}

const results: string[] = [];
for (let i = 2; i <= N; i++) {
  if (isPrime(i)) {
    results.push(String(i));
  }
}

if (results.length > 0) {
  console.log(results.join("\n"));
}

