	runTest("quantity 9 - no discount (price=10.0)", 10.0, 9, 90.0)

	// Boundary: exactly 10 (10% discount kicks in)
	runTest("quantity 10 - 10%% discount (price=10.0)", 10.0, 10, 90.0)

	// Boundary: just below 50 (10% discount)
