package main

import (
	"fmt"
	"os"
	"strconv"
)

func sieveOfEratosthenes(n int) []int {
	if n < 2 {
		return nil
	}

	isPrime := make([]bool, n+1)
	for i := range isPrime {
		isPrime[i] = true
	}
	isPrime[0] = false
	isPrime[1] = false

	for i := 2; i*i <= n; i++ {
		if isPrime[i] {
			for j := i * i; j <= n; j += i {
				isPrime[j] = false
			}
		}
	}

	var primes []int
	for i := 2; i <= n; i++ {
		if isPrime[i] {
			primes = append(primes, i)
		}
	}
	return primes
}

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintf(os.Stderr, "Usage: %s <N>\n", os.Args[0])
		os.Exit(1)
	}

	n, err := strconv.Atoi(os.Args[1])
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: invalid integer argument: %s\n", os.Args[1])
		os.Exit(1)
	}

	primes := sieveOfEratosthenes(n)
	for _, p := range primes {
		fmt.Println(p)
	}
}
```

This program:

1. **Parses** the single integer argument `N` from the command line using `strconv.Atoi`.
2. **Uses the Sieve of Eratosthenes** to efficiently find all primes up to and including `N`:
   - Creates a boolean array where index `i` represents whether `i` is prime.
   - Marks multiples of each prime (starting from its square) as non-prime.
   - Collects all remaining primes.
3. **Prints** each prime number on its own line.
4. **Prints nothing** if `N < 2` (no primes exist), since the sieve returns an empty slice and the loop simply doesn't execute.

Example usage:
```
$ go run main.go 20
2
3
5
7
11
13
17
19
```

```
$ go run main.go 1
(no output)
```

