import (
	"fmt"
	"os"
	"strconv"
)

func main() {
	if len(os.Args) < 2 {
		return
	}

	n, err := strconv.Atoi(os.Args[1])
	if err != nil {
		return
	}

	if n < 1 {
		return
	}

	a, b := 1, 1
	fmt.Println(a)
	if b <= n {
		fmt.Println(b)
	}

	for {
		next := a + b
		if next > n {
			break
		}
		fmt.Println(next)
		a, b = b, next
	}
}
```

**How it works:**

1. Parses the first command-line argument as an integer `N`.
2. If `N < 1`, exits immediately (prints nothing).
3. Otherwise, starts with the first two Fibonacci numbers (`a = 1`, `b = 1`), prints them (as long as they don't exceed `N`), then iteratively computes `next = a + b`, prints it, and shifts the window forward — stopping as soon as the next value would exceed `N`.

**Example runs:**
```
$ go run main.go 10
1
1
2
3
5
8

$ go run main.go 1
1
1

$ go run main.go -5
(nothing)
```

