package main

import (
	"fmt"
	"math"
)

func calculateDiscount(price float64, quantity int) float64 {
	if quantity < 10 {
		return price * float64(quantity)
	} else if quantity < 50 {
		return price * float64(quantity) * 0.9
	}
	return price * float64(quantity) * 0.75
}

func main() {
	epsilon := 1e-9

	tests := []struct {
		description string
		price       float64
		quantity    int
		expected    float64
	}{
		{"quantity 9 (below 10, no discount)", 10.0, 9, 10.0 * 9},
		{"quantity 10 (boundary, 10% discount)", 10.0, 10, 10.0 * 10 * 0.9},
		{"quantity 49 (below 50, 10% discount)", 10.0, 49, 10.0 * 49 * 0.9},
		{"quantity 50 (boundary, 25% discount)", 10.0, 50, 10.0 * 50 * 0.75},
		{"quantity 100 (well above 50, 25% discount)", 5.0, 100, 5.0 * 100 * 0.75},
	}

	for _, tc := range tests {
		got := calculateDiscount(tc.price, tc.quantity)
		if math.Abs(got-tc.expected) < epsilon {
			fmt.Printf("PASS: %s\n", tc.description)
		} else {
			fmt.Printf("FAIL: %s (expected: %v, got: %v)\n", tc.description, tc.expected, got)
		}
	}
}
```

**How it works:**

1. The `calculateDiscount` function is copied directly into the program.
2. A table-driven test list covers five cases:
   - **quantity 9** – just below the 10% discount threshold (no discount applied)
   - **quantity 10** – exactly at the boundary where the 10% discount kicks in
   - **quantity 49** – just below the 25% discount threshold (10% discount applied)
   - **quantity 50** – exactly at the boundary where the 25% discount kicks in
   - **quantity 100** – well above 50 to confirm the 25% discount branch works generally
3. Each test compares the actual result to the expected value using a small epsilon (`1e-9`) to avoid floating-point comparison pitfalls.
4. Results are printed as `PASS: <description>` or `FAIL: <description> (expected: X, got: Y)`.

**Expected output:**
```
PASS: quantity 9 (below 10, no discount)
PASS: quantity 10 (boundary, 10% discount)
PASS: quantity 49 (below 50, 10% discount)
PASS: quantity 50 (boundary, 25% discount)
PASS: quantity 100 (well above 50, 25% discount)
```

