package main

import (
	"fmt"
	"math"
	"os"
	"strconv"
)

func isPrime(n int) bool {
	if n < 2 {
		return false
	}
	if n == 2 {
		return true
	}
	if n%2 == 0 {
		return false
	}
	limit := int(math.Sqrt(float64(n)))
	for i := 3; i <= limit; i += 2 {
		if n%i == 0 {
			return false
		}
	}
	return true
}

func main() {
	if len(os.Args) < 2 {
		return
	}
	n, err := strconv.Atoi(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, "error: invalid integer argument")
		os.Exit(1)
	}
	for i := 2; i <= n; i++ {
		if isPrime(i) {
			fmt.Println(i)
		}
	}
}
```

**How it works:**

1. **Reads the argument** – `os.Args[1]` is parsed into an integer `N`. If parsing fails, an error is printed to stderr and the program exits with code 1.

2. **Iterates from 2 to N** – For each candidate `i`, it checks primality via `isPrime`.

3. **`isPrime`** – Uses trial division:
   - Numbers less than 2 are not prime.
   - 2 is prime.
   - Even numbers > 2 are not prime.
   - For odd candidates, only odd divisors up to √n are tested.

4. **Output** – Each prime is printed on its own line. If `N < 2`, the loop never executes, so nothing is printed.

**Example usage:**

```
$ go run main.go 10
2
3
5
7

$ go run main.go 1
(no output)
```

