        if (name == "null" || string.IsNullOrEmpty(name)) return;
        string[] parts = name.Split(' ');
        var rel = new JsonObject
        {
            ["FirstName"] = parts[0],
            ["LastName"] = parts[parts.Length - 1],
            ["Relationship"] = relationship
        };
