    {
        ["FirstName"] = firstName,
        ["LastName"] = lastName,
        ["Birthday"] = birthdayStr,
        ["Age"] = age,
        ["Relatives"] = relatives
    };

    results.Add(person);
}

var options = new JsonSerializerOptions { WriteIndented = true };
